class Solution {
  public int sharedDrawersFloorTicket(int[][] drawers, int k) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {Set<Integer>right=new HashSet<>();for(int x:a[1])right.add(x);Set<Integer>both=new TreeSet<>();for(int x:a[0])if(right.contains(x))both.add(x);out.addAll(both);}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.min(answer,x);return answer;
  }
}
